#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 int minimumWhiteTiles(string floor,int numCarpets,int carpetLen){int n=floor.size();vector<vector<int>> dp(numCarpets+1,vector<int>(n+1,0));
  for(int j=0;j<=numCarpets;++j)for(int i=1;i<=n;++i){dp[j][i]=dp[j][i-1]+(floor[i-1]=='1');
   if(j)dp[j][i]=min(dp[j][i],dp[j-1][max(0,i-carpetLen)]);
  }return dp[numCarpets][n];
 }
};
